import numpy as np
from PIL import Image
import produce as p
UID='unit_embercourt_beaconline_writguard';LEGACY=p.ROOT/'art/animation/source/poses'/UID
FRAMES=json.loads((LEGACY/'packing.json').read_bytes())['frames']
IDENTITY=('One original Beaconline Writguard, adult bearded human man, charcoal steel plate armor with brass trim, red-plumed closed crown helmet with open bearded face, red scarf and torn red-black cloak, black armored trousers and metal boots. Exactly TWO arms and TWO legs. SCREEN LEFT RIGHT hand grips the tall single wooden lantern STANDARD with brass finial, one large amber lantern, two smaller hanging lanterns and red-gold pennon strips; standard is NOT a weapon or staff with magic. SCREEN RIGHT LEFT hand holds ONE long wooden-shafted single steel axe blade while the red charcoal brass-rimmed lantern-emblem shield is strapped to that SAME LEFT FOREARM. Original axe, shield and standard remain separate identifiable equipment, never held by extra hands. Same face, armor and original weapon proportions throughout. ')
PLATE=(' Locked original elevated three-quarter orthographic camera facing screen right, full body and ALL standard/axe/shield tips in960x544 with generous margins, fixed body scale and root centered. Uniform saturated GREEN RGB0,255,0 background, no floor, shadow, scenery, text, other people, sparks, magic, smoke or trails. No root drift, body resizing, duplicate limbs or extra weapons. ')
def ref(i):
 f=dict(FRAMES[i]);f['source']=(LEGACY/f['source']).relative_to(p.ROOT).as_posix();f['alpha_noise_cutoff']=8;return f
def config(clip,refs,guides,last,description,seed):
 c=dict(unit_id=UID,clip=clip,canvas=[960,544],anchor=[480,480],scale=.5,key_rgb=[0,255,0],seed=seed,references=refs,guides=guides,last=last,prompt=(IDENTITY+description+PLATE).strip(),protected_foreground_chroma=0,tiled_decode=dict(tile_size=512,overlap=64,temporal_size=16,temporal_overlap=4))
 out=p.SOURCE_DIR/(clip+'_h3_v1');out.mkdir(exist_ok=True);assert not (out/'submission.json').exists();p.write(out/'config.json',c);p.prepare(out,c)
 measured=[]
 for i in range(len(refs)):
  a=np.asarray(Image.open(out/f'guide_{i}_rgba.png')).astype(int);opaque=a[:,:,3]>=245;measured.append(int((a[:,:,1]-np.maximum(a[:,:,0],a[:,:,2]))[opaque].max()))
 c['protected_foreground_chroma']=max(measured)+2;p.write(out/'config.json',c);p.verify(out,c);p.write(out/'foreground_measurement.json',dict(opaque_alpha_minimum=245,original_guide_green_minus_max_red_blue=measured,margin=2,protected_foreground_chroma=c['protected_foreground_chroma']))
if __name__=='__main__':
 config('move',[ref(13),ref(2),ref(3),ref(4),ref(5)],[[20,1],[38,2],[64,3],[84,4]],0,'One reciprocal WALK IN PLACE. Alternate SCREEN LEFT and SCREEN RIGHT boots through heel contact, loaded support, opposite raised knee and passing phases. SCREEN LEFT RIGHT hand carries same tall lantern standard upright, elbow absorbing gait; SCREEN RIGHT LEFT hand carries same axe lowered while original shield stays attached to LEFT forearm. Pennon strips and cloak follow real motion gently. Complete BOTH leg phases then settle into original ready. No hovering, one-legged marching, arm swap or standard stabbing.',2026102301)
 config('attack',[ref(13),ref(6),ref(7)],[[28,1],[48,2],[94,0]],0,'One controlled LEFT AXE downward swing. RIGHT hand on SCREEN LEFT keeps original tall lantern standard upright continuously. LEFT hand on SCREEN RIGHT draws its original axe up and backward28, then swings axe blade downward-forward48 through a shoulder, elbow and wrist arc. Original shield remains strapped to SAME LEFT forearm during swing, no extra hand holding shield. Left arm then lifts axe back into low ready94. Supported knee/waist transfer, stable standard and original body. No standard jab, shield bash, thrown axe or magic.',2026102302)
 config('hit',[ref(13),ref(9)],[[30,1],[88,0]],0,'One backward RECOIL and recovery. Bend knees, chest/head lean back30; RIGHT hand retains original lantern standard, LEFT hand retains axe and shield remains on left forearm. Both boots remain supported. Recover progressively through hips, knees and shoulders88 to original ready. No incoming object, hit effect, falling or altered equipment.',2026102303)
 config('defend',[ref(13),ref(8)],[[42,1]],1,'One gradual SHIELD BRACE. Bend knees and lower hips, bring original SCREEN RIGHT LEFT forearm shield before torso42 while LEFT hand still retains its axe. SCREEN LEFT RIGHT hand holds original lantern standard upright. HOLD final supported guard, no return to ready and no axe swing, shield growth or extra arm.',2026102304)
 config('death',[ref(13),ref(12)],[],1,'One uninterrupted gradual physical collapse into supplied grounded corpse. Knees flex, hips descend, body loses support, rolls gently onto side with head SCREEN LEFT and boots SCREEN RIGHT. RIGHT hand lowers original lantern standard with arm and lets standard lie diagonally on ground; LEFT hand lowers original axe while shield stays on LEFT forearm. Keep exactly two arms and two legs and all original equipment. Every prop follows physical gravity, no floating upright standard, no sudden shrinking, teleporting, standing back up or long kneeling plateau. Last half-second lies motionless grounded.',2026102305)
 p.write(p.SOURCE_DIR/'runtime_registration.json',dict(unit_id=UID,reference_height=256,output_scale=.5,ground_anchor=[480,480],source_family_scaling='Retain original .55/.145/.44 source-wide scales unchanged.',measured_reference_height=211,reason='Reviewed articulated idle208-211px; inherited ready/contact212-221px and brace207px share original armored body/standard scale. Fallen101px keeps folded anatomy and grounded equipment. No per-frame normalization.'))
 p.write(p.SOURCE_DIR/'delivery.json',dict(takes=[n+'_h3_v1' for n in ['move','attack','hit','defend','death']],preserved_accepted_clips=['idle'],visual_review=dict(status='pending',notes='Solo Beaconline Writguard. Preserve original eight articulated idle phases; six dedicated original H3 actions required, support guide being prepared. Review reciprocal gait, two arms, left hand axe plus left forearm shield, right hand lantern standard, grounded fall.')))
